  `amount` DECIMAL(15,2) NOT NULL,
  `status` ENUM('ACTIVE','PAUSED','ENDED') NOT NULL DEFAULT 'ACTIVE',
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE INDEX `billing_schedules_contract_id_key` (`contract_id`),
  INDEX `billing_schedules_status_next_invoice_date_idx` (`status`, `next_invoice_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `invoices` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `public_id` CHAR(26) NOT NULL,
  `code` VARCHAR(32) NOT NULL,
  `customer_id` BIGINT UNSIGNED NOT NULL,
  `facility_id` BIGINT UNSIGNED NOT NULL,
  `contract_id` BIGINT UNSIGNED NULL,
  `reservation_id` BIGINT UNSIGNED NULL,
  `type` ENUM('RESERVATION','MOVE_IN','RECURRING','RENEWAL','AD_HOC','SETTLEMENT') NOT NULL,
  `period_start` DATE NULL,
  `period_end` DATE NULL,
  `issue_date` DATE NOT NULL,
  `due_date` DATE NOT NULL,
  `status` ENUM('DRAFT','ISSUED','PARTIALLY_PAID','PAID','VOID','REFUNDED','PARTIALLY_REFUNDED','WRITTEN_OFF') NOT NULL DEFAULT 'ISSUED',
  `subtotal` DECIMAL(15,2) NOT NULL,
  `discount_total` DECIMAL(15,2) NOT NULL DEFAULT 0,
  `tax_total` DECIMAL(15,2) NOT NULL DEFAULT 0,
  `total` DECIMAL(15,2) NOT NULL,
  `amount_paid` DECIMAL(15,2) NOT NULL DEFAULT 0,
  `amount_credited` DECIMAL(15,2) NOT NULL DEFAULT 0,
  `balance_due` DECIMAL(15,2) GENERATED ALWAYS AS ((`total` - `amount_paid` - `amount_credited`)) STORED NULL,
  `currency` CHAR(3) NOT NULL DEFAULT 'VND',
  `late_fee_applied` BOOLEAN NOT NULL DEFAULT 0,
  `dispute_hold` BOOLEAN NOT NULL DEFAULT 0,
  `move_in_due` BOOLEAN NOT NULL DEFAULT 0,
  `pdf_media_id` BIGINT UNSIGNED NULL,
  `paid_at` DATETIME(3) NULL,
  `voided_at` DATETIME(3) NULL,
  `void_reason` VARCHAR(255) NULL,
  `version` INT UNSIGNED NOT NULL DEFAULT 0,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE INDEX `invoices_public_id_key` (`public_id`),
  UNIQUE INDEX `invoices_code_key` (`code`),
  INDEX `invoices_customer_id_status_idx` (`customer_id`, `status`),
  INDEX `invoices_contract_id_due_date_idx` (`contract_id`, `due_date`),
  INDEX `invoices_facility_id_status_due_date_idx` (`facility_id`, `status`, `due_date`),
  INDEX `invoices_issue_date_idx` (`issue_date`),
  CONSTRAINT `invoices_chk_1` CHECK (`contract_id` IS NOT NULL OR `reservation_id` IS NOT NULL),
  CONSTRAINT `invoices_chk_2` CHECK (`total` = `subtotal` - `discount_total` + `tax_total`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `invoice_items` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `invoice_id` BIGINT UNSIGNED NOT NULL,
  `item_type` ENUM('RENT','DEPOSIT','FEE','DISCOUNT','PRORATION','DAMAGE','ADJUSTMENT') NOT NULL,
  `fee_type_id` BIGINT UNSIGNED NULL,
  `description` VARCHAR(255) NOT NULL,
  `quantity` DECIMAL(8,2) NOT NULL DEFAULT 1,
  `unit_price` DECIMAL(15,2) NOT NULL,
  `amount` DECIMAL(15,2) NOT NULL,
  `tax_rate` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `tax_amount` DECIMAL(15,2) NOT NULL DEFAULT 0,
  `service_period_start` DATE NULL,
  `service_period_end` DATE NULL,
  `promotion_id` BIGINT UNSIGNED NULL,
  `source_type` VARCHAR(40) NULL,
  `source_id` BIGINT UNSIGNED NULL,
  `created_by` BIGINT UNSIGNED NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  INDEX `invoice_items_invoice_id_idx` (`invoice_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `payments` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `public_id` CHAR(26) NOT NULL,
  `code` VARCHAR(32) NOT NULL,
  `customer_id` BIGINT UNSIGNED NOT NULL,
  `facility_id` BIGINT UNSIGNED NOT NULL,
  `method` ENUM('GATEWAY','CASH','BANK_TRANSFER','CARD_ON_FILE','CREDIT_BALANCE') NOT NULL,
  `provider` ENUM('VNPAY','MOMO','STRIPE','MOCK') NULL,
  `provider_txn_id` VARCHAR(128) NULL,
  `provider_order_ref` VARCHAR(128) NULL,
  `amount` DECIMAL(15,2) NOT NULL,
  `currency` CHAR(3) NOT NULL DEFAULT 'VND',
  `status` ENUM('PENDING','SUCCEEDED','FAILED','CANCELLED','EXPIRED','PARTIALLY_REFUNDED','REFUNDED') NOT NULL DEFAULT 'PENDING',
  `failure_code` VARCHAR(64) NULL,
  `failure_message` VARCHAR(255) NULL,
  `attempt_no` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `idempotency_key` VARCHAR(64) NULL,
  `recorded_by` BIGINT UNSIGNED NULL,
  `bank_reference` VARCHAR(100) NULL,
  `intended_invoice_ids` JSON NULL,
  `paid_at` DATETIME(3) NULL,
  `expires_at` DATETIME(3) NULL,
  `refunded_amount` DECIMAL(15,2) NOT NULL DEFAULT 0,
  `raw_response` JSON NULL,
  `reconciliation_status` ENUM('UNRECONCILED','MATCHED','MISMATCH') NOT NULL DEFAULT 'UNRECONCILED',
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE INDEX `payments_public_id_key` (`public_id`),
  UNIQUE INDEX `payments_code_key` (`code`),
  UNIQUE INDEX `payments_idempotency_key_key` (`idempotency_key`),
  INDEX `payments_customer_id_created_at_idx` (`customer_id`, `created_at`),
  INDEX `payments_status_created_at_idx` (`status`, `created_at`),
  INDEX `payments_facility_id_paid_at_idx` (`facility_id`, `paid_at`),
  UNIQUE INDEX `payments_provider_provider_txn_id_key` (`provider`, `provider_txn_id`),
  CONSTRAINT `payments_chk_1` CHECK (`refunded_amount` <= `amount`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `payment_allocations` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `payment_id` BIGINT UNSIGNED NOT NULL,
  `invoice_id` BIGINT UNSIGNED NOT NULL,
