  UNIQUE INDEX `payment_allocations_payment_id_invoice_id_key` (`payment_id`, `invoice_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `payment_webhook_events` (
