  PRIMARY KEY (`id`),
  UNIQUE INDEX `payment_webhook_events_provider_event_id_key` (`provider`, `event_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `refunds` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `public_id` CHAR(26) NOT NULL,
  `payment_id` BIGINT UNSIGNED NULL,
  `customer_id` BIGINT UNSIGNED NOT NULL,
  `facility_id` BIGINT UNSIGNED NOT NULL,
  `contract_id` BIGINT UNSIGNED NULL,
  `reservation_id` BIGINT UNSIGNED NULL,
  `reason` ENUM('CANCELLATION','DEPOSIT_RETURN','OVERPAYMENT','DUPLICATE_CHARGE','LATE_WEBHOOK','GOODWILL','PREPAID_RETURN') NOT NULL,
  `amount` DECIMAL(15,2) NOT NULL,
  `status` ENUM('PENDING_APPROVAL','APPROVED','PROCESSING','SUCCEEDED','FAILED','MANUAL_REQUIRED','REJECTED') NOT NULL DEFAULT 'PENDING_APPROVAL',
  `method` ENUM('ORIGINAL_METHOD','BANK_TRANSFER','CASH') NOT NULL DEFAULT 'ORIGINAL_METHOD',
  `bank_info_enc` VARBINARY(512) NULL,
  `provider_refund_id` VARCHAR(128) NULL,
  `required_approver_role` ENUM('CUSTOMER','FACILITY_STAFF','FACILITY_MANAGER','BUSINESS_OPS_MANAGER','SYSTEM_ADMIN') NOT NULL DEFAULT 'FACILITY_MANAGER',
  `requested_by` BIGINT UNSIGNED NULL,
  `approved_by` BIGINT UNSIGNED NULL,
  `approved_at` DATETIME(3) NULL,
  `processed_at` DATETIME(3) NULL,
  `attempts` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `manual_reference` VARCHAR(100) NULL,
  `note` VARCHAR(500) NULL,
  `ticket_id` BIGINT UNSIGNED NULL,
  `idempotency_key` VARCHAR(64) NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE INDEX `refunds_public_id_key` (`public_id`),
  UNIQUE INDEX `refunds_idempotency_key_key` (`idempotency_key`),
  INDEX `refunds_status_created_at_idx` (`status`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `deposits` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `customer_id` BIGINT UNSIGNED NOT NULL,
  `reservation_id` BIGINT UNSIGNED NOT NULL,
  `contract_id` BIGINT UNSIGNED NULL,
  `amount` DECIMAL(15,2) NOT NULL,
  `held_amount` DECIMAL(15,2) NOT NULL,
  `applied_amount` DECIMAL(15,2) NOT NULL DEFAULT 0,
  `refunded_amount` DECIMAL(15,2) NOT NULL DEFAULT 0,
  `forfeited_amount` DECIMAL(15,2) NOT NULL DEFAULT 0,
  `status` ENUM('HELD','APPLIED','PARTIALLY_REFUNDED','REFUNDED','FORFEITED') NOT NULL DEFAULT 'HELD',
  `source_payment_id` BIGINT UNSIGNED NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE INDEX `deposits_reservation_id_key` (`reservation_id`),
  CONSTRAINT `deposits_chk_1` CHECK (`applied_amount` + `refunded_amount` + `forfeited_amount` <= `amount`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `credit_notes` (
